// Pixel Runner – simple endless side‑scroll runner
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = 800;
  const H = canvas.height = 200;

  // Game state
  let speed = 2; // pixels per frame
  let score = 0;
  let gameOver = false;

  // Player
  const player = {
    x: 50,
    y: H - 20,
    w: 10,
    h: 10,
    vy: 0,
    jumpStrength: -6,
    onGround: true,
    draw() {
      ctx.fillStyle = '#000';
      ctx.fillRect(this.x, this.y, this.w, this.h);
    },
    update() {
      this.vy += 0.3; // gravity
      this.y += this.vy;
      if (this.y + this.h >= H) {
        this.y = H - this.h;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
    jump() {
      if (this.onGround) {
        this.vy = this.jumpStrength;
        this.onGround = false;
      }
    }
  };

  // Obstacles – simple vertical blocks of varying height
  const obstacles = [];
  function spawnObstacle() {
    const gap = 120 + Math.random() * 80; // distance from previous obstacle
    const lastX = obstacles.length ? obstacles[obstacles.length - 1].x : W;
    const x = Math.max(lastX + gap, W);
    const h = 20 + Math.random() * 30;
    obstacles.push({ x, y: H - h, w: 10, h });
  }

  // Input handling
  window.addEventListener('keydown', e => {
    if (e.code === 'Space') player.jump();
  });
  canvas.addEventListener('pointerdown', () => player.jump());

  // Main loop
  function loop() {
    if (gameOver) return;
    ctx.clearRect(0, 0, W, H);

    // Update player
    player.update();
    player.draw();

    // Update obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const ob = obstacles[i];
      ob.x -= speed;
      ctx.fillStyle = '#666';
      ctx.fillRect(ob.x, ob.y, ob.w, ob.h);

      // Collision
      if (
        player.x < ob.x + ob.w &&
        player.x + player.w > ob.x &&
        player.y < ob.y + ob.h &&
        player.y + player.h > ob.y
      ) {
        gameOver = true;
      }

      // Remove off‑screen obstacles
      if (ob.x + ob.w < 0) obstacles.splice(i, 1);
    }

    // Spawn new obstacles periodically
    if (obstacles.length === 0 || obstacles[obstacles.length - 1].x < W - 200) {
      spawnObstacle();
    }

    // Increase speed gradually
    speed += 0.0005;
    score += speed;
    ctx.fillStyle = '#000';
    ctx.font = '14px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);

    if (!gameOver) requestAnimationFrame(loop);
    else {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W / 2 - 60, H / 2);
    }
  }

  // Start
  spawnObstacle();
  loop();
})();
